package mx.gob.sedesol.basegestor.gestionescolar.v2;

import static org.testng.Assert.assertEquals;
import static org.testng.Assert.assertFalse;
import static org.testng.Assert.assertTrue;

import java.util.ArrayList;
import java.util.Date;
import java.util.List;

import org.testng.annotations.Test;

import mx.gob.sedesol.basegestor.commons.dto.gestionescolar.v2.CausaIndisponibilidadOfertaV2;
import mx.gob.sedesol.basegestor.commons.dto.gestionescolar.v2.CausaPendienteUnidadV2;
import mx.gob.sedesol.basegestor.commons.dto.gestionescolar.v2.CodigoReglaCurricularV2;
import mx.gob.sedesol.basegestor.commons.dto.gestionescolar.v2.ContextoEvaluacionCurricularV2DTO;
import mx.gob.sedesol.basegestor.commons.dto.gestionescolar.v2.EstadoUnidadCurricularV2;
import mx.gob.sedesol.basegestor.commons.dto.gestionescolar.v2.EvaluacionCargaAcademicaV2DTO;
import mx.gob.sedesol.basegestor.commons.dto.gestionescolar.v2.ResultadoEvaluacionCurricularV2DTO;
import mx.gob.sedesol.basegestor.commons.dto.gestionescolar.v2.TrazaReglaAplicadaV2DTO;
import mx.gob.sedesol.basegestor.commons.dto.gestionescolar.v2.UnidadEvaluacionCurricularV2DTO;
import mx.gob.sedesol.basegestor.service.impl.gestionescolar.v2.EvaluacionCurricularV2ServiceImpl;

/** F4A-U-01 a F4A-U-23: RN-6.3 como prioridad académica en modo sombra. */
public class EvaluacionCurricularV2Fase4ATest {

    private final EvaluacionCurricularV2ServiceImpl service = new EvaluacionCurricularV2ServiceImpl();

    @Test public void f4AU01RegularNoConstruyeRutaRegularizacion() { EvaluacionCargaAcademicaV2DTO e=evaluar(contexto(obligatorias(1L,3))).getEvaluacionCargaAcademica();assertFalse(e.getAplicaRn63()); }
    @Test public void f4AU02UnaReprobadaOfertadaEsPrioritaria() { EvaluacionCargaAcademicaV2DTO e=evaluar(contexto(reprobada(10L))).getEvaluacionCargaAcademica();assertTrue(e.getAplicaRn63());assertTrue(e.getUdsReprobadasPrioritarias().contains(Long.valueOf(10L)));assertTrue(e.getUdsReprobadasOfertadas().contains(Long.valueOf(10L))); }
    @Test public void f4AU03DosReprobadasOfertadasSonPrioritarias() { EvaluacionCargaAcademicaV2DTO e=evaluar(contexto(reprobada(20L),reprobada(21L))).getEvaluacionCargaAcademica();assertEquals(e.getUdsReprobadasPrioritarias().size(),2);assertEquals(e.getUdsReprobadasOfertadas().size(),2); }
    @Test public void f4AU04TresReprobadasOfertadasSonPrioritarias() { EvaluacionCargaAcademicaV2DTO e=evaluar(contexto(reprobada(30L),reprobada(31L),reprobada(32L))).getEvaluacionCargaAcademica();assertEquals(e.getUdsReprobadasOfertadas().size(),3); }
    @Test public void f4AU05ReprobadaPrecedeObligatoriasCompatibles() { ContextoEvaluacionCurricularV2DTO c=contexto(reprobada(40L));c.getUnidades().addAll(obligatorias(41L,2));EvaluacionCargaAcademicaV2DTO e=evaluar(c).getEvaluacionCargaAcademica();assertTrue(e.getUdsReprobadasPrioritarias().contains(Long.valueOf(40L)));assertEquals(e.getUdsObligatoriasCompatibles().size(),2); }
    @Test public void f4AU06ReprobadaPrecedeOptativasCompatibles() { ContextoEvaluacionCurricularV2DTO c=contexto(reprobada(50L));c.getUnidades().addAll(optativas(51L,2));EvaluacionCargaAcademicaV2DTO e=evaluar(c).getEvaluacionCargaAcademica();assertTrue(e.getUdsReprobadasPrioritarias().contains(Long.valueOf(50L)));assertEquals(e.getUdsOptativasCompatibles().size(),2); }
    @Test public void f4AU07OrdenReprobadasObligatoriasOptativasEsEstable() { ContextoEvaluacionCurricularV2DTO c=contexto(reprobada(60L),reprobada(61L),obligatoria(62L),optativa(63L));EvaluacionCargaAcademicaV2DTO e=evaluar(c).getEvaluacionCargaAcademica();assertEquals(e.getUdsReprobadasPrioritarias().size(),2);assertTrue(e.getUdsObligatoriasCompatibles().contains(Long.valueOf(62L)));assertTrue(e.getUdsOptativasCompatibles().contains(Long.valueOf(63L))); }
    @Test public void f4AU08ReprobadaSinOfertaPermanecePrioritaria() { UnidadEvaluacionCurricularV2DTO u=reprobada(70L);u.setOfertada(Boolean.FALSE);u.setCausaIndisponibilidadOferta(CausaIndisponibilidadOfertaV2.UD_NO_OFERTADA_PERIODO);EvaluacionCargaAcademicaV2DTO e=evaluar(contexto(u)).getEvaluacionCargaAcademica();assertTrue(e.getUdsReprobadasPrioritarias().contains(Long.valueOf(70L)));assertTrue(e.getUdsReprobadasNoDisponibles().contains(Long.valueOf(70L)));assertTrue(e.getCausasIndisponibilidadRegularizacion().toString().contains("SIN_OFERTA")); }
    @Test public void f4AU09ReprobadaSinCupoNoSeConvierteEnSinOferta() { UnidadEvaluacionCurricularV2DTO u=reprobada(80L);u.setCupoDisponibleConocido(Boolean.FALSE);u.setCausaIndisponibilidadOferta(CausaIndisponibilidadOfertaV2.SIN_CUPO);EvaluacionCargaAcademicaV2DTO e=evaluar(contexto(u)).getEvaluacionCargaAcademica();assertTrue(e.getCausasIndisponibilidadRegularizacion().toString().contains("SIN_CUPO"));assertFalse(e.getCausasIndisponibilidadRegularizacion().toString().contains("SIN_OFERTA")); }
    @Test public void f4AU10ReprobadaSeriadaRequiereRevision() { UnidadEvaluacionCurricularV2DTO u=reprobada(90L);u.setSeriacionDirectaConocida(Boolean.TRUE);EvaluacionCargaAcademicaV2DTO e=evaluar(contexto(u)).getEvaluacionCargaAcademica();assertTrue(e.getUdsReprobadasNoDisponibles().contains(Long.valueOf(90L)));assertTrue(e.getCausasIndisponibilidadRegularizacion().toString().contains("SERIACION")); }
    @Test public void f4AU11EmpateDePrioritariasSinDesempateRequiereRevision() { ContextoEvaluacionCurricularV2DTO c=contexto(reprobadas(100L,7));EvaluacionCargaAcademicaV2DTO e=evaluar(c).getEvaluacionCargaAcademica();assertTrue(e.getRequiereRevisionRegularizacion());assertEquals(e.getUdsEmpatadasRegularizacion().size(),7); }
    @Test public void f4AU12MultiplesIntentosSiguenSiendoUnaSolaUdPrioritaria() { UnidadEvaluacionCurricularV2DTO u=reprobada(110L);u.setIntentosFallidosHistoricosConfiables(Integer.valueOf(3));u.getReferenciasHistoricas().add("INTENTO:1");u.getReferenciasHistoricas().add("INTENTO:2");u.getReferenciasHistoricas().add("INTENTO:3");EvaluacionCargaAcademicaV2DTO e=evaluar(contexto(u)).getEvaluacionCargaAcademica();assertEquals(e.getUdsReprobadasPrioritarias().size(),1); }
    @Test public void f4AU13BajaParcialNoSeClasificaComoReprobada() { UnidadEvaluacionCurricularV2DTO u=obligatoria(120L);u.setEstado(EstadoUnidadCurricularV2.BAJA_PARCIAL);u.setCausa(CausaPendienteUnidadV2.BAJA_PARCIAL);EvaluacionCargaAcademicaV2DTO e=evaluar(contexto(u)).getEvaluacionCargaAcademica();assertFalse(e.getAplicaRn63());assertTrue(e.getUdsReprobadasPrioritarias().isEmpty()); }
    @Test public void f4AU14NoCursadaNoSeClasificaComoReprobada() { EvaluacionCargaAcademicaV2DTO e=evaluar(contexto(obligatoria(130L))).getEvaluacionCargaAcademica();assertFalse(e.getAplicaRn63());assertTrue(e.getUdsReprobadasPrioritarias().isEmpty()); }
    @Test public void f4AU15CuatroReprobadasDetectanRn64SinEfectos() { EvaluacionCargaAcademicaV2DTO e=evaluar(contexto(reprobadas(140L,4))).getEvaluacionCargaAcademica();assertTrue(e.getRn64AplicableEnFuturaFase());assertTrue(e.getAplicaRn63()); }
    @Test public void f4AU16CincoReprobadasDetectanRn64SinEfectos() { EvaluacionCargaAcademicaV2DTO e=evaluar(contexto(reprobadas(150L,5))).getEvaluacionCargaAcademica();assertTrue(e.getRn64AplicableEnFuturaFase()); }
    @Test public void f4AU17QuintoDesde2027DetectaRn61() { ContextoEvaluacionCurricularV2DTO c=contexto(reprobada(160L));c.setSemestreObjetivo(Integer.valueOf(5));c.setPeriodoNormativo("2027-1");assertTrue(evaluar(c).getEvaluacionCargaAcademica().getCtr01Rn61Procedente()); }
    @Test public void f4AU18TerceroNoDetectaRn61() { ContextoEvaluacionCurricularV2DTO c=contexto(reprobada(170L));c.setSemestreObjetivo(Integer.valueOf(3));c.setPeriodoNormativo("2027-1");assertFalse(evaluar(c).getEvaluacionCargaAcademica().getCtr01Rn61Procedente()); }
    @Test public void f4AU19SeptimoNoDetectaRn61() { ContextoEvaluacionCurricularV2DTO c=contexto(reprobada(180L));c.setSemestreObjetivo(Integer.valueOf(7));c.setPeriodoNormativo("2027-1");assertFalse(evaluar(c).getEvaluacionCargaAcademica().getCtr01Rn61Procedente()); }
    @Test public void f4AU20SituacionNoDeterminadaRequiereRevision() { EvaluacionCargaAcademicaV2DTO e=evaluar(contexto(indeterminada(190L))).getEvaluacionCargaAcademica();assertFalse(e.getAplicaRn63());assertTrue(e.getRequiereRevisionRegularizacion()); }
    @Test public void f4AU21DuplicadoTecnicoNoDuplicaPrioridad() { UnidadEvaluacionCurricularV2DTO a=reprobada(200L),b=reprobada(200L);a.setBloque("B1");b.setBloque("B2");assertEquals(evaluar(contexto(a,b)).getEvaluacionCargaAcademica().getUdsReprobadasPrioritarias().size(),1); }
    @Test public void f4AU22MismoContextoProduceMismaRuta() { ContextoEvaluacionCurricularV2DTO c=contexto(reprobada(210L),obligatoria(211L));EvaluacionCargaAcademicaV2DTO a=evaluar(c).getEvaluacionCargaAcademica(),b=evaluar(c).getEvaluacionCargaAcademica();assertEquals(a.getUdsReprobadasPrioritarias(),b.getUdsReprobadasPrioritarias());assertEquals(a.getCargaDisponibleRegularizacion(),b.getCargaDisponibleRegularizacion()); }
    @Test public void f4AU23NoTieneEfectoProductivoYRegistraRn63() { UnidadEvaluacionCurricularV2DTO u=reprobada(220L);ResultadoEvaluacionCurricularV2DTO r=evaluar(contexto(u));assertFalse(r.getEfectosProductivosAplicados());assertTrue(u.getOfertada());assertTrue(r.getReglasEvaluadas().contains(CodigoReglaCurricularV2.RN_6_3));assertTrue(tieneTraza(r.getDecisiones().get(0).getTrazas())); }

    private ResultadoEvaluacionCurricularV2DTO evaluar(ContextoEvaluacionCurricularV2DTO c){return service.evaluarSombra(c);} private ContextoEvaluacionCurricularV2DTO contexto(UnidadEvaluacionCurricularV2DTO...us){ContextoEvaluacionCurricularV2DTO c=new ContextoEvaluacionCurricularV2DTO();c.setVersionReglas("PE2027-V1");c.setFechaEvaluacion(new Date(0L));c.setSemestreObjetivo(Integer.valueOf(3));c.setActividadAcademicaComprobada(Boolean.TRUE);c.setPermanenciaDentroLimiteComprobada(Boolean.TRUE);c.setDictaminacionEgresoConocida(Boolean.TRUE);c.setOportunidadesMejoraUtilizadas(Integer.valueOf(0));for(UnidadEvaluacionCurricularV2DTO u:us)c.getUnidades().add(u);return c;} private ContextoEvaluacionCurricularV2DTO contexto(List<UnidadEvaluacionCurricularV2DTO> us){return contexto(us.toArray(new UnidadEvaluacionCurricularV2DTO[us.size()]));}
    private boolean tieneTraza(List<TrazaReglaAplicadaV2DTO> trazas){for(TrazaReglaAplicadaV2DTO t:trazas)if(t.getCodigoRegla()==CodigoReglaCurricularV2.RN_6_3)return true;return false;}
    private List<UnidadEvaluacionCurricularV2DTO> obligatorias(Long i,int n){return unidades(i,n,"Obligatoria");} private List<UnidadEvaluacionCurricularV2DTO> optativas(Long i,int n){return unidades(i,n,"Optativa");} private List<UnidadEvaluacionCurricularV2DTO> reprobadas(Long i,int n){List<UnidadEvaluacionCurricularV2DTO> r=new ArrayList<UnidadEvaluacionCurricularV2DTO>();for(int x=0;x<n;x++)r.add(reprobada(Long.valueOf(i.longValue()+x)));return r;} private List<UnidadEvaluacionCurricularV2DTO> unidades(Long i,int n,String tipo){List<UnidadEvaluacionCurricularV2DTO> r=new ArrayList<UnidadEvaluacionCurricularV2DTO>();for(int x=0;x<n;x++)r.add(pendiente(Long.valueOf(i.longValue()+x),tipo));return r;}
    private UnidadEvaluacionCurricularV2DTO obligatoria(Long i){return pendiente(i,"Obligatoria");} private UnidadEvaluacionCurricularV2DTO optativa(Long i){return pendiente(i,"Optativa");} private UnidadEvaluacionCurricularV2DTO reprobada(Long i){UnidadEvaluacionCurricularV2DTO u=pendiente(i,"Obligatoria");u.setEstado(EstadoUnidadCurricularV2.REPROBADA);u.setCausa(CausaPendienteUnidadV2.REPROBACION);u.setReprobacionVigenteConocida(Boolean.TRUE);u.setReprobacionPeriodoPrevioConocida(Boolean.TRUE);return u;} private UnidadEvaluacionCurricularV2DTO indeterminada(Long i){UnidadEvaluacionCurricularV2DTO u=pendiente(i,"Obligatoria");u.setEstado(EstadoUnidadCurricularV2.NO_DETERMINADO);u.setCausa(null);return u;} private UnidadEvaluacionCurricularV2DTO pendiente(Long i,String tipo){UnidadEvaluacionCurricularV2DTO u=new UnidadEvaluacionCurricularV2DTO();u.setIdPrograma(i);u.setClave("UD"+i);u.setTipoUd(tipo);u.setEstado(EstadoUnidadCurricularV2.NO_CURSADA);u.setCausa(CausaPendienteUnidadV2.NO_CURSAMIENTO);u.setOfertada(Boolean.TRUE);u.setGrupoActivoConocido(Boolean.TRUE);u.setCupoDisponibleConocido(Boolean.TRUE);u.setSeleccionableOrigen(Boolean.TRUE);return u;}
}
